begin;
create schema cms_test;
create table cms_test.results(label text primary key);
create table cms_test.state(value jsonb);
grant usage on schema cms_test to anon,authenticated,service_role;
grant select,insert,update on all tables in schema cms_test to anon,authenticated,service_role;
create function cms_test.assert(ok boolean,label text) returns void language plpgsql as $$ begin
  if ok is distinct from true then raise exception 'ASSERTION FAILED: %',label; end if;
  insert into cms_test.results values(label);
end; $$;
create function cms_test.error(command text,expected text,label text,state text default 'P0001') returns void language plpgsql as $$
declare caught boolean:=false;
begin begin execute command; exception when others then caught:=true;
  if sqlstate<>state or (expected is not null and sqlerrm<>expected) then raise exception 'ASSERTION FAILED: %, expected %/%, got %/%',label,state,expected,sqlstate,sqlerrm; end if;
end; perform cms_test.assert(caught,label); end; $$;
create function cms_test.claims(n integer) returns void language sql as $$
  select set_config('request.jwt.claims',jsonb_build_object('sub','90000000-0000-4000-8000-'||lpad(n::text,12,'0'),'session_id','91000000-0000-4000-8000-'||lpad(n::text,12,'0'))::text,true);
$$;
insert into auth.users(id,email,email_confirmed_at) select ('90000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'cms'||n||'@example.invalid',case when n=3 then null else now() end from generate_series(1,4)n;
insert into auth.sessions(id,user_id) select ('91000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('90000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,3)n;
insert into comment_private.admins values('90000000-0000-4000-8000-000000000001'),('90000000-0000-4000-8000-000000000004');
set local role anon;
select cms_test.error('select public.cms_list()',null,'anonymous cannot list private drafts','42501');
select cms_test.error($q$select public.cms_get('profile')$q$,null,'anonymous cannot read a guessed ID','42501');
select cms_test.error('select * from cms_private.documents',null,'anonymous has no private schema access','42501');
select cms_test.error('select public.cms_jobs()',null,'anonymous cannot see release snapshots','42501');
set local role authenticated;
select cms_test.claims(2);
select cms_test.error('select public.cms_list()','admin_required','regular member cannot list');
select cms_test.error($q$select public.cms_initialize('[]')$q$,'admin_required','regular member cannot initialize');
select cms_test.error($q$select public.cms_save('profile','profile',0,'{}')$q$,'admin_required','regular member cannot save');
select cms_test.error($q$select public.cms_history('profile')$q$,'admin_required','regular member cannot view history');
select cms_test.error($q$select public.cms_media_list()$q$,'admin_required','regular member cannot enumerate media');
select cms_test.error($q$select public.cms_prepare_publish('profile',1,'publish',gen_random_uuid())$q$,'admin_required','regular member cannot queue publishing');
select cms_test.error('select * from cms_private.documents',null,'authenticated role cannot read private tables','42501');
select cms_test.error($q$select public.cms_service_claim(gen_random_uuid())$q$,null,'member cannot call service RPC','42501');
select cms_test.claims(3);
select cms_test.error('select public.cms_list()','email_verification_required','unverified account rejected');
select cms_test.claims(4);
select cms_test.error('select public.cms_list()','session_expired','administrator without live session rejected');
select cms_test.claims(1);
select cms_test.error($q$select public.cms_service_claim(gen_random_uuid())$q$,null,'owner cannot bypass Edge service with browser RPC','42501');
select public.cms_initialize('[{"id":"profile","kind":"profile","payload":{"zh":{"name":"original"}}},{"id":"academic","kind":"academic","payload":{}}]');
select cms_test.assert(jsonb_array_length(public.cms_list())=2,'initial public content is imported');
select public.cms_initialize('[]');
select cms_test.assert(jsonb_array_length(public.cms_list())=2,'initialize cannot overwrite existing content');
select public.cms_save('profile','profile',1,'{"zh":{"name":"private new name"}}');
select cms_test.assert(public.cms_get('profile')->>'revision'='2','save increments revision');
select cms_test.assert(public.cms_get('profile')->'published_payload'->'zh'->>'name'='original','saving does not publish');
select cms_test.assert(public.cms_get('profile',1)->'payload'->'zh'->>'name'='original','old version retained');
select cms_test.error($q$select public.cms_save('profile','profile',1,'{}')$q$,'cms_conflict','stale editor cannot overwrite');
select cms_test.error($q$select public.cms_trash('profile',2,true)$q$,'cms_fixed_document','fixed page cannot be deleted');
select cms_test.error($q$select public.cms_save('profile','post',2,'{}')$q$,'cms_conflict','document kind immutable');
select cms_test.error($q$select public.cms_save('92000000-0000-4000-8000-000000000001','post',0,'{"slug":"../evil"}')$q$,'cms_invalid_slug','path traversal rejected');
select public.cms_save('92000000-0000-4000-8000-000000000001','post',0,'{"slug":"first-post","zh":{"body":"private body"}}');
select cms_test.assert(public.cms_get('92000000-0000-4000-8000-000000000001')->'published_payload'='null'::jsonb,'new post stays private');
select public.cms_prepare_publish('92000000-0000-4000-8000-000000000001',1,'publish','93000000-0000-4000-8000-000000000001');
select cms_test.assert(public.cms_prepare_publish('92000000-0000-4000-8000-000000000001',1,'publish','93000000-0000-4000-8000-000000000001')->>'state'='queued','queue retry uses same request ID');
select cms_test.error($q$select public.cms_prepare_publish('profile',2,'publish','93000000-0000-4000-8000-000000000001')$q$,'cms_request_conflict','request ID cannot be repurposed');
select cms_test.error($q$select public.cms_prepare_publish('profile',2,'publish','93000000-0000-4000-8000-000000000002')$q$,'cms_publish_pending','one publisher at a time');
select cms_test.error($q$select public.cms_save('92000000-0000-4000-8000-000000000001','post',1,'{"slug":"first-post"}')$q$,'cms_publish_pending','queued document frozen');
select public.cms_save('profile','profile',2,'{"zh":{"name":"independent private edit"}}');
reset role;
select cms_test.assert((select documents::text not like '%independent private edit%' and documents::text not like '%private new name%' from cms_private.jobs where id='93000000-0000-4000-8000-000000000001'),'unrelated drafts excluded from release');
set local role service_role;
insert into cms_test.state select public.cms_service_claim('93000000-0000-4000-8000-000000000001');
select cms_test.error($q$select public.cms_service_claim('93000000-0000-4000-8000-000000000001')$q$,'cms_publish_busy','lease prevents concurrent duplicate execution');
select cms_test.error($q$select public.cms_service_finish('93000000-0000-4000-8000-000000000001',gen_random_uuid(),'committed',repeat('a',40))$q$,'cms_lease_lost','wrong lease cannot finalize');
select public.cms_service_finish('93000000-0000-4000-8000-000000000001',(select (value->>'lease')::uuid from cms_test.state),'failed',null,'offline');
update cms_test.state set value=public.cms_service_claim('93000000-0000-4000-8000-000000000001');
select cms_test.assert((select value->>'state'='publishing' from cms_test.state),'failed job can retry');
select public.cms_service_finish('93000000-0000-4000-8000-000000000001',(select (value->>'lease')::uuid from cms_test.state),'committed',repeat('a',40));
set local role authenticated;
select cms_test.claims(1);
select cms_test.assert(public.cms_get('92000000-0000-4000-8000-000000000001')->'published_payload'->'zh'->>'body'='private body','successful commit advances published content');
select cms_test.assert(public.cms_get('profile')->'published_payload'->'zh'->>'name'='original','other draft remains unpublished');
select cms_test.error($q$select public.cms_save('92000000-0000-4000-8000-000000000001','post',1,'{"slug":"changed"}')$q$,'cms_slug_locked','published post keeps URL and comment identity');
select public.cms_save('92000000-0000-4000-8000-000000000002','post',0,'{"slug":"first-post"}');
select cms_test.error($q$select public.cms_prepare_publish('92000000-0000-4000-8000-000000000002',1,'publish',gen_random_uuid())$q$,'cms_slug_taken','duplicate published URL blocked');
select public.cms_prepare_publish('92000000-0000-4000-8000-000000000001',1,'trash','93000000-0000-4000-8000-000000000002');
select cms_test.assert((public.cms_get('92000000-0000-4000-8000-000000000001')->>'deleted')::boolean=false,'queued deletion does not hide current website');
set local role service_role;
update cms_test.state set value=public.cms_service_claim('93000000-0000-4000-8000-000000000002');
select public.cms_service_finish('93000000-0000-4000-8000-000000000002',(select (value->>'lease')::uuid from cms_test.state),'committed',repeat('b',40));
set local role authenticated;
select cms_test.claims(1);
select cms_test.assert((public.cms_get('92000000-0000-4000-8000-000000000001')->>'deleted')::boolean,'published deletion enters trash');
select cms_test.assert(public.cms_get('92000000-0000-4000-8000-000000000001')->'published_payload'='null'::jsonb,'published deletion retracts published record');
select public.cms_trash('92000000-0000-4000-8000-000000000001',2,false);
select cms_test.assert(public.cms_get('92000000-0000-4000-8000-000000000001')->'published_payload'='null'::jsonb,'restore is a draft, not automatic publication');
select cms_test.assert(jsonb_array_length(public.cms_history('92000000-0000-4000-8000-000000000001'))=3,'trash and restore retain history');
select public.cms_media_save('94000000-0000-4000-8000-000000000001','photo.webp','private caption');
insert into storage.objects(bucket_id,name,metadata) values('cms-media','94000000-0000-4000-8000-000000000001.webp','{"mimetype":"image/webp"}');
select cms_test.assert((select count(*) from storage.objects where bucket_id='cms-media')=1,'owner reads private image metadata');
select cms_test.assert(not cms_private.media_access('../arbitrary.webp',true),'storage path must match a registered asset');
select cms_test.claims(2);
select cms_test.assert((select count(*) from storage.objects where bucket_id='cms-media')=0,'regular member cannot read private images');
select cms_test.error($q$insert into storage.objects(bucket_id,name) values('cms-media','94000000-0000-4000-8000-000000000002.webp')$q$,null,'regular member cannot upload','42501');
select cms_test.claims(1);
select public.cms_save('92000000-0000-4000-8000-000000000001','post',3,'{"slug":"first-post","body":"/media/94000000-0000-4000-8000-000000000001.webp"}');
select cms_test.error($q$select public.cms_media_save('94000000-0000-4000-8000-000000000001','photo.webp','',true)$q$,'cms_media_in_use','referenced draft image cannot be recycled');
select public.cms_save('92000000-0000-4000-8000-000000000001','post',4,'{"slug":"first-post"}');
select public.cms_media_save('94000000-0000-4000-8000-000000000001','photo.webp','',true);
select cms_test.assert((public.cms_media_list()->0->>'deleted')::boolean,'unused image enters recycle bin');
select cms_test.assert(cms_private.media_access('94000000-0000-4000-8000-000000000001.webp',false),'historical image remains readable by owner');
select cms_test.assert(not cms_private.media_access('94000000-0000-4000-8000-000000000001.webp',true),'recycled image does not permit new upload');
select public.cms_media_save('94000000-0000-4000-8000-000000000001','photo.webp','restored',false);
select cms_test.assert(not (public.cms_media_list()->0->>'deleted')::boolean,'image can be restored');
reset role;
delete from auth.sessions where user_id='90000000-0000-4000-8000-000000000001';
set local role authenticated;
select cms_test.error('select public.cms_list()','session_expired','sign-out revokes database access');
select cms_test.assert(not cms_private.media_access('94000000-0000-4000-8000-000000000001.webp',false),'sign-out revokes private storage access');
reset role;
select cms_test.assert((select not public from storage.buckets where id='cms-media'),'CMS image bucket is private');
select count(*) as cms_assertions_passed from cms_test.results;
rollback;
